// Radiografía de un texto: cuatro formas de medirlo
const enc = new TextEncoder();                      // convierte texto a bytes UTF-8
const seg = new Intl.Segmenter("es", { granularity: "grapheme" });

function radiografia(s) {
  const puntos = [...s].map(c => "U+" + c.codePointAt(0).toString(16).toUpperCase().padStart(4, "0"));
  const bytes = [...enc.encode(s)].map(b => b.toString(16).toUpperCase().padStart(2, "0"));
  console.log(JSON.stringify(s));
  console.log("  length (unidades UTF-16): " + s.length);
  console.log("  puntos de código:         " + puntos.length + "  " + puntos.join(" "));
  console.log("  bytes en UTF-8:           " + bytes.length + "  " + bytes.join(" "));
  console.log("  lo que ve la persona:     " + [...seg.segment(s)].length);
}

radiografia("ñandú");
radiografia("😀");
radiografia("e\u0301");              // una «e» seguida de un acento combinante
radiografia("🇦🇷");

// Dos formas de escribir la misma «é»
const a = "\u00e9", b = "e\u0301";
console.log("¿iguales?", a === b, "| tras normalizar a NFC:", a.normalize("NFC") === b.normalize("NFC"));

// Quitar tildes: la ñ es otra letra y hay que protegerla
const sinTildes = t => t.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
console.log(sinTildes("Canción"), sinTildes("ñandú"));   // la segunda perdió la ñ

// Ordenar: por punto de código la ñ queda al final
const lista = ["ñu", "nu", "oso", "zorro"];
console.log([...lista].sort().join(", "));
console.log([...lista].sort((x, y) => x.localeCompare(y, "es")).join(", "));
